<script lang="ts">import {onMount,getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createInterWarehouseTransfersState} from '../state/interWarehouseTransfersState.svelte';import type {RecordInterWarehouseTransfer} from '../../domain/entity/InterWarehouseTransfer';const i18n=getContext<I18nState>('i18n');const vm=createInterWarehouseTransfersState();let open=$state(false),itemId=$state(''),fromWarehouseId=$state(''),fromBinId=$state(''),toWarehouseId=$state(''),toBinId=$state(''),quantity=$state('1'),reason=$state('');onMount(()=>{void vm.load();});async function create(){const v:RecordInterWarehouseTransfer={itemId:Number(itemId),sourceWarehouseId:Number(fromWarehouseId),sourceBinId:Number(fromBinId),destinationWarehouseId:Number(toWarehouseId),destinationBinId:Number(toBinId),quantity:Number(quantity),reason};if(await vm.create(v)){open=false;itemId='';fromWarehouseId='';fromBinId='';toWarehouseId='';toBinId='';quantity='1';reason='';}}</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Movimientos entre almacenes')}</h1><p>{i18n.t('Transfiere existencias entre ubicaciones de almacenes distintos; el backend registra el movimiento de forma atómica.')}</p></div><button class="primary" onclick={()=>open=!open}>{i18n.t('Nueva transferencia')}</button></header>{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if open}<form class="editor" onsubmit={e=>{e.preventDefault();void create();}}><label>{i18n.t('ID de producto')}<input type="number" min="1" required bind:value={itemId}/></label><label>{i18n.t('Almacén origen')}<input type="number" min="1" required bind:value={fromWarehouseId}/></label><label>{i18n.t('Ubicación origen')}<input type="number" min="1" required bind:value={fromBinId}/></label><label>{i18n.t('Almacén destino')}<input type="number" min="1" required bind:value={toWarehouseId}/></label><label>{i18n.t('Ubicación destino')}<input type="number" min="1" required bind:value={toBinId}/></label><label>{i18n.t('Cantidad')}<input type="number" min="1" required bind:value={quantity}/></label><label class="wide">{i18n.t('Motivo')}<input maxlength="500" bind:value={reason}/></label><div class="actions"><button type="button" onclick={()=>open=false}>{i18n.t('Cancelar')}</button><button class="primary" disabled={vm.saving}>{i18n.t('Transferir inventario')}</button></div></form>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else if vm.rows.length===0}<p class="empty">{i18n.t('No hay movimientos registrados.')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Fecha')}</th><th>SKU</th><th>{i18n.t('Producto')}</th><th>{i18n.t('Origen')}</th><th>{i18n.t('Destino')}</th><th>{i18n.t('Cantidad')}</th><th>{i18n.t('Responsable')}</th><th>{i18n.t('Estado')}</th></tr></thead><tbody>{#each vm.rows as r (r.transferId)}<tr><td>{r.transferredAt??'—'}</td><td>{r.lines[0]?.sku??'—'}</td><td>{r.lines[0]?.itemName??r.lines[0]?.itemId}</td><td>{r.sourceWarehouseName} ({r.sourceWarehouseCode}) · {r.sourceBinCode}</td><td>{r.destinationWarehouseName} ({r.destinationWarehouseCode}) · {r.destinationBinCode}</td><td>{r.lines[0]?.quantity}</td><td>{r.transferredBy}</td><td>{r.status}</td></tr>{/each}</tbody></table></div>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}.primary{background:var(--navy);color:white;border-color:var(--navy)}.editor{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem;padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--card)}.editor label{display:grid;gap:.3rem;color:var(--slate);font-size:.8rem}.editor input{min-height:39px;border:1px solid var(--line);border-radius:8px;padding:.5rem;background:var(--card);color:var(--ink)}.wide,.actions{grid-column:1/-1}.actions{display:flex;justify-content:flex-end}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);margin:1rem 0}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.82rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.7rem;text-transform:uppercase}.error{color:var(--danger)}.empty{color:var(--slate);padding:2rem 0}@media(max-width:640px){header{align-items:flex-start;flex-direction:column}.editor{grid-template-columns:1fr}}</style>